 insert into public.lesson_sections(lesson_id,title,content,order_index) values(l,'How to approach this task','Use a past passive when the action matters more than the agent: A schedule was piloted. While can contrast two outcomes. Rather than presents a preferred alternative. A balanced recommendation acknowledges evidence against it.',1),(l,'Worked example','A company piloted a four-day schedule for six months. Output remained stable, while staff reported lower stress. However, customers faced longer waits on Fridays. The director proposed staggered days off rather than closing the office on a single day.',2);
