 insert into public.lesson_sections(lesson_id,title,content,order_index) values(l,'How to approach this task','Hedging calibrates a claim to evidence: may indicate and is consistent with preserve uncertainty. Having controlled for income does not mean having controlled for every confounder. Use concessive clauses to preserve this distinction: Although income was controlled for, self-selection remained possible.',1),(l,'Worked example','Researchers found an association between access to green space and reported wellbeing. The observational study controlled for income, but could not rule out residential self-selection. Its authors cautioned that the findings warranted further investigation rather than a definitive causal claim.',2);
insert into public.exercises(lesson_id,exercise_type,prompt,passage,order_index) values(l,'fill_blank','The results ___ an association, without establishing causation.','Researchers found an association between access to green space and reported wellbeing. The observational study controlled for income, but could not rule out residential self-selection. Its authors cautioned that the findings warranted further investigation rather than a definitive causal claim.',1) returning id into e;
insert into public.exercise_options(exercise_id,option_text,is_correct,explanation,order_index) values(e,'prove beyond doubt',false,'Review the scenario. Hedging calibrates a claim to evidence: may indicate and is consistent with preserve uncertainty. Having controlled for income does not mean having controlled for every confounder. Use concessive clauses to preserve this distinction: Although income was controlled for, self-selection remained possible.',1);
insert into public.exercise_options(exercise_id,option_text,is_correct,explanation,order_index) values(e,'suggest',true,'Correct. Hedging calibrates a claim to evidence: may indicate and is consistent with preserve uncertainty. Having controlled for income does not mean having controlled for every confounder. Use concessive clauses to preserve this distinction: Although income was controlled for, self-selection remained possible.',2);
insert into public.exercise_options(exercise_id,option_text,is_correct,explanation,order_index) values(e,'rule out',false,'Review the scenario. Hedging calibrates a claim to evidence: may indicate and is consistent with preserve uncertainty. Having controlled for income does not mean having controlled for every confounder. Use concessive clauses to preserve this distinction: Although income was controlled for, self-selection remained possible.',3);
