 insert into public.lesson_sections(lesson_id,title,content,order_index) values(l,'How to approach this task','Read for the overall situation first, then distinguish stated details from conclusions. Support each answer with a phrase from the passage. Hedging calibrates a claim to evidence: may indicate and is consistent with preserve uncertainty. Having controlled for income does not mean having controlled for every confounder. Use concessive clauses to preserve this distinction: Although income was controlled for, self-selection remained possible.',1),(l,'Worked example','Researchers found an association between access to green space and reported wellbeing. The observational study controlled for income, but could not rule out residential self-selection. Its authors cautioned that the findings warranted further investigation rather than a definitive causal claim.',2);
